import { SummarizeInput } from './src/modules/ai/domain/schemas';

async function testSummarize() {
    console.log('--- Starting End-to-End Summarize Test ---');

    const sampleText = `
        The rapid advancement of artificial intelligence (AI) has brought about significant changes in various industries. 
        In healthcare, AI is being used to analyze medical images, predict patient outcomes, and develop personalized treatment plans. 
        In finance, AI algorithms are employed for fraud detection, algorithmic trading, and risk assessment. 
        The automotive industry is also seeing the impact of AI with the development of self-driving cars and advanced driver-assistance systems. 
        Despite these benefits, there are concerns about the ethical implications of AI, including bias in algorithms, privacy issues, and the potential for job displacement. 
        As AI continues to evolve, it is crucial to address these challenges and ensure that the technology is developed and used responsibly.
    `;

    const input: SummarizeInput = {
        text: sampleText,
        length: 'short'
    };

    console.log('Input Text Length:', sampleText.length);
    console.log('Target Length:', input.length);
    console.log('Sending request to Ollama (Gemma 2B)...');

    try {
        const startTime = Date.now();
        const result = await summarizeText(input);
        const endTime = Date.now();

        console.log('\n--- Result ---');
        console.log('Summary:', result.summary);
        console.log('\nExecution Time:', (endTime - startTime) / 1000, 'seconds');
        console.log('--- Test Completed ---');
    } catch (error) {
        console.error('\n--- Error ---');
        console.error(error);
        console.log('--- Test Failed ---');
    }
}

testSummarize();

