async function testApiSummarize() {
    const baseUrl = 'http://localhost:9002';

    console.log('--- Starting API Summarize Test ---');

    // 1. Login
    console.log('Logging in as user@arkan.com...');
    const loginResponse = await fetch(`${baseUrl}/api/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            email: 'user@arkan.com',
            password: 'user123'
        })
    });

    if (!loginResponse.ok) {
        console.error('Login failed:', await loginResponse.text());
        return;
    }

    const cookie = loginResponse.headers.get('set-cookie');
    if (!cookie) {
        console.error('No session cookie received');
        return;
    }

    console.log('Login successful. Session cookie obtained.');

    // 2. Call Summarize API
    const sampleText = `
        Quantum computing is a type of computing that uses quantum-mechanical phenomena, such as superposition and entanglement. 
        Quantum computers are different from binary digital electronic computers based on transistors. 
        Whereas common digital computing requires that the data be encoded into binary digits (bits), each of which is always in one of two definite states (0 or 1), 
        quantum computation uses quantum bits, or qubits, which can be in a superposition of states. 
        A quantum computer with a given number of qubits can in principle process an exponential number of states simultaneously. 
        Quantum computing is a subfield of quantum information science, which also includes quantum cryptography and quantum communications.
    `;

    console.log('Calling Summarize API...');
    const summarizeResponse = await fetch(`${baseUrl}/api/writing-tools/summarize`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Cookie': cookie
        },
        body: JSON.stringify({
            flow: 'summarize',
            text: sampleText,
            length: 'short'
        })
    });

    if (!summarizeResponse.ok) {
        console.error('Summarize API failed:', await summarizeResponse.text());
        return;
    }

    const result = await summarizeResponse.json();
    console.log('\n--- API Response ---');
    console.log(JSON.stringify(result, null, 2));
    console.log('\n--- Test Completed ---');
}

testApiSummarize();

