async function testDynamicCounter() {
    const baseUrl = 'http://localhost:9002';
    const guestIp = '192.168.1.200';

    console.log('--- Testing Dynamic Usage Counter ---');

    // 1. Initial Check
    console.log('Checking initial guest usage stats...');
    const guestLogin = await fetch(`${baseUrl}/api/auth/guest`, { method: 'POST' });
    const cookie = guestLogin.headers.get('set-cookie');

    const getUsage = async () => {
        const resp = await fetch(`${baseUrl}/api/stats/usage`, {
            headers: { 'Cookie': cookie!, 'x-forwarded-for': guestIp }
        });
        return await resp.json();
    };

    let stats = await getUsage();
    console.log(`Initial Remaining: ${stats.remainingFreeGenerations} / ${stats.totalLimit}`);

    // 2. Consume 1 generation
    console.log('\nConsuming 1 generation...');
    const genResp = await fetch(`${baseUrl}/api/writing-tools/summarize`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Cookie': cookie!,
            'x-forwarded-for': guestIp
        },
        body: JSON.stringify({ text: 'Dynamic counter test', length: 'short' })
    });

    if (genResp.ok) {
        const data = await genResp.json();
        console.log(`AI Response usageMetadata: ${data.usageMetadata?.remaining} remaining`);
    }

    // 3. Final Check
    stats = await getUsage();
    console.log(`\nFinal Remaining (via API): ${stats.remainingFreeGenerations} / ${stats.totalLimit}`);

    if (stats.remainingFreeGenerations === 4) {
        console.log('--- Test Passed ---');
    } else {
        console.error('Test Failed: Remaining count mismatch.');
    }
}

testDynamicCounter();

